        assert x["cramers_v_ci"][0] <= x["cramers_v"] <= x["cramers_v_ci"][1]
        assert "cluster bootstrap" in x["cramers_v_ci_method"]
        assert x["cramers_v"] == pytest.approx(float(cramers_v(np.array(x["table"]))), abs=1e-6)

